insert into news (date_label,sort_date,category,title,body,tags,service_key,is_video,video_url,source_name,source_url,status,office_key,image_url,sources) values ('17 Nov 2026','2026-11-17','Safety','Farmer''s alert helps troops safely remove explosive near Damboa','A farmer working his land on the outskirts of Damboa town found an unexploded device on 13 November and alerted troops on patrol, who safely disposed of it. Anyone who finds a suspicious object should not touch it and should report it to the nearest security post.',array[]::text[],null,false,null,'The News Chronicle','https://thenews-chronicle.com/farmer-alerts-soldiers-as-unexploded-bomb-is-found-near-damboa-borno/','published',null,null,'[]'::jsonb);
