insert into heritage (sort,icon,title,body,note) values (1,'forest','Sambisa Forest','Part of the Sambisa Forest lies in Damboa. From around 1970 it was a safari destination where visitors watched leopards, lions, elephants and hyenas, and 62 bird species have been recorded there. In 1991 it became part of the Chad Basin National Park.','A symbol of the natural heritage Damboa hopes to restore.');
insert into heritage (sort,icon,title,body,note) values (2,'market','Damboa Main Market','For generations the meeting point of farmers and traders from across southern Borno. Destroyed in 2014 and reopened in 2016.',null);
insert into heritage (sort,icon,title,body,note) values (3,'wheat','Farmlands and gum arabic','Grains, groundnuts, beans and gum arabic from Damboa''s farmlands feed the region and its markets.',null);
insert into heritage (sort,icon,title,body,note) values (4,'drum','Marghi language and culture','The Marghi language, with its Damboa and Mulgwai varieties, and the shared Marghi–Kanuri heritage of Damboa families.','Festivals and cultural sites to be documented with elders.');
insert into heritage (sort,icon,title,body,note) values (5,'pot','The calabash trade','Calabash farming drew Kanuri traders to Damboa and shaped the town''s mixed heritage.',null);
insert into heritage (sort,icon,title,body,note) values (6,'pin','Historic sites','Old settlements, the District Head''s palace, early schools and mosques.','To be added with the elders'' history project.');
