insert into pages (slug,office_key,name,role,subtitle,years,photo_url,tag,bio,priorities,office_info) values ('chairman','chairman','Hon. Ali Mohammed Kauji','Executive Chairman','Damboa Local Government','Jan 2024 – present','/img/chair.jpg','Hon. Ali Mohammed Kauji','Hon. Ali Mohammed Kauji (APC) was elected Executive Chairman of Damboa Local Government in January 2024 and returned in the council elections of 13 December 2025. He was sworn in for his current term on 29 January 2026. His administration works in line with the transformation agenda of His Excellency, Prof. Babagana Umara Zulum, mni, FNSE, Executive Governor of Borno State.',array['Resettlement and security','Education','Health and nutrition','Agriculture and markets','Youth, skills and digital jobs','Roads, water and sanitation']::text[],'LGA Secretariat, Maiduguri Road, Damboa. Visiting days to be added.');
insert into pages (slug,office_key,name,role,subtitle,years,photo_url,tag,bio,priorities,office_info) values ('mai-bukar','state-member','Dr. Mohammed Mai Bukar, PhD','Member, Borno State House of Assembly','Damboa State Constituency','','/img/member.jpg','Dr. Mohammed Mai Bukar, PhD','Dr. Mohammed Mai Bukar holds a doctorate (PhD) and is the All Progressives Congress (APC) candidate for Damboa State Constituency in the Borno State House of Assembly election of 6 February 2027. He previously served as an aide to the Executive Governor of Borno State, Prof. Babagana Umara Zulum, and in 2026 obtained the APC nomination forms for the Damboa seat.',array['Education and skills','Health and nutrition','Security and resettlement','Farming and markets','Youth and digital jobs','Roads and water']::text[],'Damboa town – address, phone and opening hours to be added.');
insert into settings (key,value) values ('welcome_en','"In line with the transformation agenda of His Excellency, Prof. Babagana Umara Zulum, mni, FNSE, Executive Governor of Borno State, I welcome you to the official website of Damboa Local Government. Dear people of Damboa, this website is our new front door. Here you will find what your council is doing, the projects in every ward, and how to reach us. It belongs to all of us, across every ward and every community. Tell us what you need, follow our progress, and hold us to our promises. Together we will keep building a Damboa we are proud of."'::jsonb) on conflict (key) do update set value = excluded.value;
insert into settings (key,value) values ('welcome_ha','"Bisa tsarin sauyi na Mai Girma Gwamna, Farfesa Babagana Umara Zulum, mni, FNSE, Gwamnan Jihar Borno, ina maraba da ku zuwa shafin hukuma na Karamar Hukumar Damboa. Ya ku al''ummar Damboa, wannan shafin shi ne sabuwar kofarmu. A nan za ku ga abin da karamar hukumarku ke yi, ayyukan da ake yi a kowace mazaba, da yadda za ku same mu. Namu ne baki daya, a kowace mazaba da kowace al''umma. Ku fada mana bukatunku, ku bi ci gabanmu, ku kuma rike mu da alkawuranmu. Tare za mu ci gaba da gina Damboa da za mu yi alfahari da ita."'::jsonb) on conflict (key) do update set value = excluded.value;
insert into settings (key,value) values ('hero_en','"The home of the Marghi people and a centre of agriculture and commerce in southern Borno. Rebuilding, reconnecting and moving forward together."'::jsonb) on conflict (key) do update set value = excluded.value;
insert into settings (key,value) values ('hero_ha','"Gidan al''ummar Marghi kuma cibiyar noma da kasuwanci a kudancin Borno. Muna sake ginawa, sake hadewa da ci gaba tare."'::jsonb) on conflict (key) do update set value = excluded.value;
